    [Fact]
    public void All25CompleteSourceRecordsMatch150IndependentConditionalBitAndValueOracles()
    {
        using var profiles = JsonDocument.Parse(PilotProfilesJson); using var provenance = JsonDocument.Parse(PilotProvenanceJson);
        using var manifest = JsonDocument.Parse(PilotSourceManifestJson); using var seeds = JsonDocument.Parse(PilotSeedVectorsJson);
        using var vectors = JsonDocument.Parse(DifficultyVectorsJson);
        var cohort = profiles.RootElement.EnumerateArray().Select(x => new RetailNpcSourceProfile(x)).ToDictionary(x => x.NpcId);
        Assert.Equal(25, cohort.Count); Assert.Equal(150, vectors.RootElement.GetArrayLength());
        var dataset = new RetailNpcStaticDataset(PilotDatasetId, PilotManifestHash, cohort, 63287, 117, 0,
            ImmutableArray<RetailNpcArtifactReceipt>.Empty, provenance.RootElement, manifest.RootElement);
        foreach (var vector in vectors.RootElement.EnumerateArray())
        {
            int id = vector.GetProperty("id").GetInt32();
            var projected = RetailNpcTemplateProjection.Project(dataset, id, new(PilotDatasetId, PilotManifestHash, "USA"));
            Assert.True(projected.Success, string.Join(";", projected.Issues)); var source = projected.Inputs!;
            var pin = seeds.RootElement.EnumerateArray().Single(x => x.GetProperty("id").GetInt32() == id);
            Assert.Equal(pin.GetProperty("raw_sha256").GetString(), source.Receipt.RawRecordSha256);
            Assert.Equal(pin.GetProperty("file_sha256").GetString(), source.Receipt.SourceFileSha256);
            Assert.Equal(pin.GetProperty("raw_tree_sha256").GetString(), Hash(Encoding.UTF8.GetBytes(source.RawRecord.GetRawText())));
            Assert.Equal(pin.GetProperty("byte_start").GetInt64(), source.Receipt.ByteStart);
            Assert.Equal(pin.GetProperty("byte_end").GetInt64(), source.Receipt.ByteEndExclusive);
            int ratio = vector.GetProperty("ratio").GetInt32(), count = vector.GetProperty("count").GetInt32();
            var level = Level(source); var table = Table(source, ratio); var context = Context(source, level, table, count);
            var result = RetailNpcDifficultyConstruction.Construct(source, level, table, 1, context);
            Assert.True(result.Success, string.Join(";", result.Issues)); var plan = result.Plan!;
            Assert.Equal(vector.GetProperty("active").GetBoolean(), plan.Predicate.ApplySecondLevel);
            Assert.Equal(14, plan.Fields.Count); Assert.Equal(14, RetailNpcDifficultyConstruction.Contracts.Length);
            CheckOracle(vector.GetProperty("initial"), plan.InitialHpOnSet);
            foreach (var field in vector.GetProperty("fields").EnumerateObject())
            {
                var actual = plan.Fields[field.Name]; Assert.Equal(field.Value.GetProperty("input_base").GetInt64(), actual.Source.NativeOperand);
                CheckOracle(field.Value, actual);
                Assert.Equal(plan.Predicate.ApplySecondLevel, actual.Applied);
            }
            foreach (var boost in vector.GetProperty("boosts").EnumerateObject())
                Assert.Equal(boost.Value.GetInt64(), plan.CommonTailBoostSources[boost.Name].NativeOperand);
            Assert.Equal(plan.Predicate.ApplySecondLevel ? 14 : 0, plan.OrderedWrites.Count(x => x.Stage == "SecondLevelDifficulty" && plan.Fields.ContainsKey(x.Field)));
            Assert.Equal(plan.Predicate.ApplySecondLevel ? 2 : 0, plan.OrderedWrites.Count(x => x.Rule.Contains("transient-zero", StringComparison.Ordinal)));
            Assert.Equal(12, plan.OrderedWrites.Count(x => x.Rule.Contains("shadow-copy", StringComparison.Ordinal)));
            Assert.Equal(2, plan.OrderedWrites.Count(x => x.Rule.Contains("template-signed16-overwrite", StringComparison.Ordinal)));
            Assert.Equal(source.Receipt, plan.SourceReceipt); Assert.Equal(level.Receipt, plan.LevelRatioTableReceipt);
            Assert.Equal(table.Receipt, plan.DifficultyTableReceipt); Assert.Equal((uint?)0u, plan.Context.MasterObjectId);
            Assert.Equal((uint?)0u, plan.Context.SourceRelatedObjectId);
            Assert.False(plan.RuntimeObservationVerified); Assert.False(plan.EffectiveActorValueVerified); Assert.False(plan.ActivationReady);
            Assert.False(RetailNpcInitializationRules.Assess(source).CanConstructEffectiveInputs);
        }
    }

    [Theory]
    [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)] [InlineData(4)] [InlineData(5)] [InlineData(6)] [InlineData(7)]
    [InlineData(8)] [InlineData(9)] [InlineData(10)] [InlineData(11)] [InlineData(12)] [InlineData(13)] [InlineData(14)] [InlineData(15)]
    public void FixedNativeBitOraclesIncludeCvttOverflowNarrowingAndDistinctSetPredicate(int ordinal)
    {
        using var document = JsonDocument.Parse(DifficultyBoundariesJson); var v = document.RootElement[ordinal];
        bool hp = v.GetProperty("hp_extra_factor").GetBoolean(); int maximum = v.GetProperty("maximum").GetInt32();
        string field = hp ? "max_hp" : maximum == 65000 ? "min_damage" : maximum == 500000 ? "physical_defend"
            : maximum == 700 ? "physical_critical_damage_reduce" : "magical_resist";
        var fixture = new Fixture(); fixture.Set(field, v.GetProperty("input_base").GetInt32());
        var source = fixture.Inputs(); int ratio = v.GetProperty("ratio").GetInt32(), count = v.GetProperty("counter").GetInt32();
        var plan = Plan(source, ratio, count);
        var actual = hp ? plan.InitialHpOnSet : plan.Fields[field];
        CheckOracle(v, actual); Assert.Equal(v.GetProperty("expected").GetInt64(), actual.Value);
        if (ordinal is 8 or 9) { Assert.False(plan.Predicate.ApplySecondLevel); Assert.Equal(16777217L, plan.Fields["max_hp"].Value); }
    }

    [Fact]
    public void TransientBoostsAreOverwrittenAndCommonTailCopiesRetainThePreEffectValues()
    {
        var fixture = new Fixture(); fixture.Set("magical_skill_boost", 65535); fixture.Set("magical_skill_boost_resist", 40000);
        fixture.Set("physical_defend", -1); fixture.Set("magical_resist", 65536); fixture.Set("min_damage", -1);
        fixture.Set("stat_ratio", 0);
        var plan = Plan(fixture.Inputs(), 47, 1);
        Assert.Equal(0L, plan.Fields["physical_defend"].Value); Assert.Equal(9999L, plan.Fields["magical_resist"].Value);
        Assert.Equal(65000L, plan.Fields["min_damage"].Value);
        foreach (var (name, actor, shadow, value) in new[] { ("magical_skill_boost", "0x1502", "0x182c", -1L),
            ("magical_skill_boost_resist", "0x1504", "0x182e", -25536L) })
        {
            var writes = plan.OrderedWrites.Where(x => x.Field == name).ToArray(); Assert.Equal(3, writes.Length);
            Assert.Equal((actor, 0L), (writes[0].ActorOffset, writes[0].Value));
            Assert.Equal((actor, value), (writes[1].ActorOffset, writes[1].Value));
            Assert.Equal((shadow, value), (writes[2].ActorOffset, writes[2].Value));
        }
        foreach (var contract in RetailNpcDifficultyConstruction.Contracts.Where(x => x.CommonTailCopyOffset is not null))
            Assert.Contains(plan.OrderedWrites, x => x.ActorOffset == contract.CommonTailCopyOffset && x.Value == plan.Fields[contract.Field].Value);
        Assert.Contains("stat_ratio", plan.UntouchedDomains); Assert.Contains("hp_regen", plan.UntouchedDomains);
        Assert.Equal(RetailNpcSourcePresence.ExplicitZero, plan.Source.StatRatio.Presence);
        Assert.Equal((int?)0, plan.Source.StatRatio.ParsedValue); // This unit does not invent an effective/default ratio.
    }

    [Theory]
    [InlineData(false)] [InlineData(true)]
    public void SourceAbsenceAndExplicitZeroSurviveNativeHpConstruction(bool explicitZero)
    {
        var fixture = new Fixture(); if (explicitZero) fixture.Set("max_hp", 0);
        var plan = Plan(fixture.Inputs(), 47, 0); var hp = plan.Fields["max_hp"];
        Assert.Equal(explicitZero ? RetailNpcSourcePresence.ExplicitZero : RetailNpcSourcePresence.Absent, hp.Source.Presence);
        Assert.Equal(1L, hp.Source.ConstructorValue); Assert.Equal(1L, hp.Value); Assert.Equal(1L, plan.InitialHpOnSet.Value);
        Assert.Equal(explicitZero ? 1 : 0, hp.Source.Lexemes.Length);
        Assert.Equal(!explicitZero, hp.Source.NativeConstructorDefaultApplied);
    }

