            "related-null" => c with { SourceRelatedObjectId = null }, "related-one" => c with { SourceRelatedObjectId = 1u }, "related-max" => c with { SourceRelatedObjectId = uint.MaxValue },
            "source" => c with { ExpectedSource = source.Receipt with { RawRecordSha256 = new('f', 64) } },
            "level-table" => c with { ExpectedLevelRatioTable = level.Receipt with { SourceSha256 = new('f', 64) } },
            "difficulty-table" => c with { ExpectedDifficultyTable = table.Receipt with { ScalingSha256 = new('f', 64) } },
            "package" => c with { ExpectedPackageContextSha256 = new('f', 64) }, "record-id" => c with { ExpectedRecordId = 2 },
            "record-hash" => c with { ExpectedRecordNormalizedXmlSha256 = new('f', 64) }, "ratio" => c with { NativeStatScalingRatio = 48 },
            "counter-null" => c with { NativeCounter = null }, "kind" => c with { NativeKind = 2 },
            "fresh-template" => c with { FreshUniqueTemplate = null }, "fresh-actor" => c with { FreshActor = false },
            "profile-null" => c with { VirtualProfileRecordPresent = null }, "profile-present" => c with { VirtualProfileRecordPresent = true },
            "dual" => c with { DualWeaponFlagPresent = true }, "record-null" => c with { DifficultyRecordPresent = null },
            "world-unresolved" => c with { DynamicWorldResolved = null }, "world-object" => c with { NativeDynamicWorldObjectId = 302330000u },
            "world-base" => c with { NativeBaseWorldId = 320050000 }, "float-null" => c with { FloatContract = null },
            "float-unsupported" => c with { FloatContract = (RetailNpcDifficultyFloatContract)99 }, "epoch" => c with { Epoch = "" },
            "evidence" => c with { EvidenceReference = "" }, "origin" => c with { Origin = RetailNpcDifficultyInputOrigin.Unspecified },
            _ => c with { ActorObjectIdentity = "not-a-fixed-fixture" }
        };
        var result = RetailNpcDifficultyConstruction.Construct(source, level, table, 1, c);
        Assert.False(result.Success); Assert.Null(result.Plan); Assert.NotEmpty(result.Issues);
