    [Theory]
    [InlineData("record-id-duplicate")] [InlineData("world-key-duplicate")] [InlineData("late-world-missing")]
    [InlineData("world-id-duplicate")] [InlineData("world-name-alias")] [InlineData("ratio-duplicate")]
    [InlineData("ratio-alias")] [InlineData("ratio-overflow")] [InlineData("ratio-malformed")]
    [InlineData("non-dungeon")] [InlineData("root-text")] [InlineData("trailing")]
    [InlineData("depth")] [InlineData("custom-entity")] [InlineData("record-id-absent")]
    public void WholeTableAdmissionRejectsEveryLateDuplicateMalformedOrUnresolvedRecord(string failure)
    {
        var source = new Fixture().Inputs(); var scaling = XElement.Parse(ScalingXml(47)); var world = XElement.Parse(WorldXml);
        var row = scaling.Element("instance_scaling")!;
        switch (failure)
        {
            case "record-id-duplicate": scaling.Add(new XElement("instance_scaling", new XElement("id", 1), new XElement("instant_dungeon_name", "Other"))); world.Add(new XElement("data", new XAttribute("id", 302330001), "Other")); break;
            case "world-key-duplicate": scaling.Add(new XElement(row)); scaling.Elements().Last().Element("id")!.Value = "2"; break;
            case "late-world-missing": scaling.Add(new XElement("instance_scaling", new XElement("id", 2), new XElement("instant_dungeon_name", "Missing"))); break;
            case "world-id-duplicate": world.Add(new XElement("data", new XAttribute("id", 302330000), "Other")); break;
            case "world-name-alias": world.Add(new XElement("data", new XAttribute("id", 302330001), "idevent_solo")); break;
            case "ratio-duplicate": row.Add(new XElement("stat_scaling_ratio", 48)); break;
            case "ratio-alias": row.Add(new XElement("STAT_SCALING_RATIO", 48)); break;
            case "ratio-overflow": row.Element("stat_scaling_ratio")!.Value = "2147483648"; break;
            case "ratio-malformed": row.Element("stat_scaling_ratio")!.Value = "47junk"; break;
            case "non-dungeon": world.Element("data")!.SetAttributeValue("id", 110010000); break;
            case "root-text": scaling.Add(new XText("unexpected")); break;
            case "record-id-absent": row.Element("id")!.Remove(); break;
        }
        string xml = scaling.ToString(SaveOptions.DisableFormatting);
        if (failure == "trailing") xml += "<extra/>";
        if (failure == "depth") xml = "<instance_scalings>" + string.Concat(Enumerable.Repeat("<x>", 10)) + string.Concat(Enumerable.Repeat("</x>", 10)) + "</instance_scalings>";
        if (failure == "custom-entity") xml = "<!DOCTYPE instance_scalings [<!ENTITY custom '47'>]>" + xml.Replace("<stat_scaling_ratio>47", "<stat_scaling_ratio>&custom;", StringComparison.Ordinal);
        byte[] a = Encoding.UTF8.GetBytes(xml), b = Encoding.UTF8.GetBytes(world.ToString(SaveOptions.DisableFormatting));
        var result = RetailNpcDifficultyTableInputs.Admit(a, b, Policy(source, a, b));
        Assert.False(result.Success); Assert.Null(result.Table); Assert.NotEmpty(result.Issues);
    }

