    [Fact]
    public void ZeroAbsentUnknownDataFlavorAndBackingBytesRemainDistinctAndImmutable()
    {
        var source = new Fixture().Inputs(); byte[] a = Encoding.UTF8.GetBytes(ScalingXml(null)), b = Encoding.UTF8.GetBytes(WorldXml);
        var p = Policy(source, a, b) with { Flavor = "test", SelectedScalingRelativePath = "test/instance_scaling_test.xml" };
        var result = RetailNpcDifficultyTableInputs.Admit(a, b, p); Assert.True(result.Success); var table = result.Table!;
        var record = Assert.Single(table.Records); Assert.Equal(RetailNpcSourcePresence.Absent, record.StatScalingRatio.Presence);
        Assert.Equal(0, record.StatScalingRatio.Value); Assert.Contains("future", record.NormalizedXml, StringComparison.Ordinal);
        Assert.True(record.StatScalingRatio.NativeRecordZeroDefaultApplied);
        a[0] ^= 0xff; b[0] ^= 0xff;
        Assert.Equal(p.ExpectedScalingSha256, Hash(table.ScalingSourceBytes.AsSpan())); Assert.Equal(p.ExpectedWorldIdsSha256, Hash(table.WorldIdsSourceBytes.AsSpan()));
        Assert.False(table.LoadedRuntimeTableVerified); Assert.False(table.ActivationReady);
        var zero = Table(source, 0); Assert.Equal(RetailNpcSourcePresence.ExplicitZero, Assert.Single(zero.Records).StatScalingRatio.Presence);
        Assert.False(zero.Records[0].StatScalingRatio.NativeRecordZeroDefaultApplied);
    }

