    [Fact]
    public void ExternalAssertionsDoNotCertifyRuntimeAndDifferentRegionsCannotBeMixed()
    {
        var source = new Fixture().Inputs(); var level = Level(source); var table = Table(source, 47, external: true);
        var context = Context(source, level, table, 1) with { Origin = RetailNpcDifficultyInputOrigin.ExternalSourceAssertion, ActorObjectIdentity = "actor42" };
        var result = RetailNpcDifficultyConstruction.Construct(source, level, table, 1, context); Assert.True(result.Success);
        Assert.False(result.Plan!.RuntimeObservationVerified); Assert.False(result.Plan.EffectiveActorValueVerified); Assert.False(result.Plan.ActivationReady);
        byte[] a = Encoding.UTF8.GetBytes(ScalingXml(47)), b = Encoding.UTF8.GetBytes(WorldXml);
        var chinaResult = RetailNpcDifficultyTableInputs.Admit(a, b, Policy(source, a, b) with { ExpectedRegion = "China", SelectedWorldIdsRelativePath = "China/ID/WorldId.xml" });
        Assert.True(chinaResult.Success); var china = chinaResult.Table!;
        Assert.False(RetailNpcDifficultyConstruction.Construct(source, level, china, 1, Context(source, level, china, 1)).Success);
    }

