    {
        var dual = new Fixture(); dual.Set("dual", 1);
        var source = dual.Inputs(); var level = Level(source); var table = Table(source, 47);
        Assert.Equal("difficulty_source_dual", Assert.Single(RetailNpcDifficultyConstruction.Construct(source, level, table, 1, Context(source, level, table, 1)).Issues).Code);
        var alias = new Fixture(); alias.Add(Node("PHYSICAL_DEFEND", "1"));
        source = alias.Inputs(); level = Level(source); table = Table(source, 47);
