    }

    private static void CheckOracle(JsonElement expected, RetailNpcDifficultyFieldPlan actual)
    {
        Assert.Equal(expected.GetProperty("result").GetInt64(), actual.Value);
        var converted = expected.GetProperty("native_cvttss2si32");
        Assert.Equal(converted.ValueKind == JsonValueKind.Null ? (int?)null : converted.GetInt32(), actual.NativeCvttSigned32);
        if (expected.TryGetProperty("binary32_steps", out var steps))
        {
            Assert.Equal(steps.GetArrayLength(), actual.FloatSteps.Length);
            for (int i = 0; i < steps.GetArrayLength(); i++)
            {
                Assert.Equal(steps[i].GetProperty("operation").GetString(), actual.FloatSteps[i].Operation);
                Assert.Equal(BinaryPrimitives.ReadUInt32LittleEndian(Convert.FromHexString(steps[i].GetProperty("bits_le").GetString()!)), actual.FloatSteps[i].Binary32Bits);
            }
        }
        else Assert.Empty(actual.FloatSteps);
    }
    private static RetailNpcDifficultyPlan Plan(RetailNpcTemplateInputs source, int ratio, int count)
    {
        var level = Level(source); var table = Table(source, ratio);
        var result = RetailNpcDifficultyConstruction.Construct(source, level, table, 1, Context(source, level, table, count));
        Assert.True(result.Success, string.Join(";", result.Issues)); return result.Plan!;
    }
    private static RetailNpcDifficultyContext Context(RetailNpcTemplateInputs source, RetailNpcLevelRatioTableInputs level, RetailNpcDifficultyTableInputs table, int count) =>
        new(source.Receipt, level.Receipt, table.Receipt, table.Receipt.PackageContextSha256, 1, table.Records[0].NormalizedXmlSha256,
            "fixed-difficulty-epoch", null, "embedded-conditional-mathematical-fixture", RetailNpcDifficultyInputOrigin.FixedMathematicalFixture,
            true, true, 1, 0u, 0u, false, false, true, true, 0x80000001u, 302330000, count, table.Records[0].StatScalingRatio.Value,
            RetailNpcDifficultyFloatContract.Binary32NearestEvenMaskedInvalid);
    private static RetailNpcLevelRatioTableInputs Level(RetailNpcTemplateInputs source)
    {
        var result = RetailNpcLevelRatioTableInputs.Admit(Convert.FromBase64String(RealTableBase64), new(source.Receipt.DatasetId,
            source.Receipt.OutputManifestSha256, source.Receipt.Region, RealTableHash, "Z:/never-open/pc_stat_ratio.xml", "pc_stat_ratio.xml", "regional_missing_base_fallback"));
        Assert.True(result.Success); return result.Table!;
    }
    private static RetailNpcDifficultyTablePolicy Policy(RetailNpcTemplateInputs source, byte[] scaling, byte[] world) =>
        new(source.Receipt.DatasetId, source.Receipt.OutputManifestSha256, "USA", new('7', 64), Hash(scaling), Hash(world),
            "Z:/never-open/instance_scaling.xml", "Z:/never-open/USA/ID/WorldId.xml", "instance_scaling.xml", "USA/ID/WorldId.xml",
            RetailNpcDifficultySelection.RegionalMissingBaseFallback, RetailNpcDifficultySelection.RegionalOverride, null,
            RetailNpcDifficultyInputOrigin.FixedMathematicalFixture);
    private static RetailNpcDifficultyTableInputs Table(RetailNpcTemplateInputs source, int? ratio, bool external = false)
    {
        byte[] a = Encoding.UTF8.GetBytes(ScalingXml(ratio)), b = Encoding.UTF8.GetBytes(WorldXml); var policy = Policy(source, a, b);
        if (external) policy = policy with { Origin = RetailNpcDifficultyInputOrigin.ExternalSourceAssertion };
        var result = RetailNpcDifficultyTableInputs.Admit(a, b, policy); Assert.True(result.Success, string.Join(";", result.Issues)); return result.Table!;
    }
    private static string ScalingXml(int? ratio) => new XElement("instance_scalings", new XElement("instance_scaling",
        new XElement("id", 1), new XElement("name", "Fixture"), new XElement("instant_dungeon_name", "IDEvent_Solo"),
        ratio.HasValue ? new XElement("stat_scaling_ratio", ratio.Value) : null, new XElement("future", new XElement("ordered", "retained"))))
        .ToString(SaveOptions.DisableFormatting);
    private const string WorldXml = "<world_id><data id=\"302330000\" unknown=\"retained\">IDEvent_Solo</data></world_id>";
    private static string Hash(ReadOnlySpan<byte> bytes) => RetailNpcDifficultyTableInputs.Digest(bytes);
    private static JsonArray Node(string tag, string? value, params JsonNode[] children)
    {
        var content = new JsonArray(); if (value is not null) content.Add(value); foreach (var child in children) content.Add(child);
        return new(JsonValue.Create(tag), new JsonArray(), content);
    }
    private sealed class Fixture
    {
        private JsonArray Root { get; } = Node("npc", null, Node("id", "1"), Node("name", "One"), Node("level", "32"));
        internal void Add(JsonNode node) => Root[2]!.AsArray().Add(node);
        internal void Set(string tag, int value)
        {
            var children = Root[2]!.AsArray(); foreach (var child in children.Where(x => x![0]!.GetValue<string>() == tag).ToArray()) children.Remove(child);
            Add(Node(tag, value.ToString(CultureInfo.InvariantCulture)));
        }
        internal RetailNpcTemplateInputs Inputs()
        {
            const string path = "Z:/never-open/npcs_monsters.xml"; string d = new('d', 64), m = new('e', 64);
            var profile = new JsonObject { ["schema_version"] = 1, ["dataset_id"] = d, ["npc_id"] = 1, ["devname"] = "One", ["scalar_fields"] = new JsonObject(),
                ["raw_record"] = Root.DeepClone(), ["skill_bindings"] = new JsonArray(), ["source"] = new JsonObject { ["path"] = path, ["byte_start"] = 0,
